INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('ISO-5667-1', '1980', 'S8_6', 'Mindest-Nennweite des Probenahmerohrs bei heterogenen Flüssigkeiten (§8.6: 25 mm)', '§8.6', 'PDF p.5 (gedruckte S. 4)', ARRAY['case']::text[], '[{"name":"min_nominal_bore_mm","type":"number","unit":"mm"}]'::jsonb, 'anhaltswert', '8.6        MUESTREO EN TUBOS

Los líquidos se deben bombear a través de tubos de tamaño adecuado (por ejemplo, al muestrear líquidos heterogéneos, de conducto nominal
mínimo de 25 mm) a velocidades lineales suficientemente altas para mantener las características de flujo turbulento. Se deben evitar los recorridos
de tubo horizontal.', 'imported_unverified')
